/*
 * A183212  Second of two trees generated by floor[(3n-1)/2].
 * https://oeis.org/A183212
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   a(n) = breadth-first traversal of the binary tree whose node n
 *            has left child floor((3n-1)/2) and right child 3n, starting with
 *            root 2. The first element a(1)=2
 * Range:     u8 n <= 31, u16 n <= 1023, u32 n <= 8192, u64 n <= 8192,
 *            u128 n <= 8192, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Include standard headers required for the implementation. */
#include <stdlib.h>

seq_t a(idx_t n) {
    /* Special case: the sequence is 1‑based; return 0 for n=0 (unused). */
    if (n == 0) return (seq_t)0;

    /* A breadth‑first search queue: capacity of 2*n+10 is sufficient
       because each of the first n popped nodes generates at most two
       children. */
    size_t cap = 2 * (size_t)n + 10;
    seq_t *q = (seq_t *)malloc(cap * sizeof(seq_t));
    if (!q) return (seq_t)0;  /* Allocation failure (unlikely in tests). */

    size_t head = 0, tail = 0;
    q[tail++] = (seq_t)2;          /* Root node. */
    idx_t seen = 0;                 /* Number of terms produced. */

    while (head < tail) {
        seq_t val = q[head++];
        ++seen;
        if (seen == n) {
            free(q);
            return val;
        }

        /* Compute left and right children. */
        seq_t left  = ((val * (seq_t)3) - (seq_t)1) / (seq_t)2;
        seq_t right = val * (seq_t)3;

        /* Skip the left child when it duplicates the parent (only
           occurs at the root). */
        if (left != val) {
            if (tail >= cap) {            /* Grow the queue if needed. */
                cap *= 2;
                seq_t *tmp = (seq_t *)realloc(q, cap * sizeof(seq_t));
                if (!tmp) { free(q); return (seq_t)0; }
                q = tmp;
            }
            q[tail++] = left;
        }

        if (tail >= cap) {
            cap *= 2;
            seq_t *tmp = (seq_t *)realloc(q, cap * sizeof(seq_t));
            if (!tmp) { free(q); return (seq_t)0; }
            q = tmp;
        }
        q[tail++] = right;
    }

    /* If the loop exits without returning, n was too large for the
       allocated capacity (impossible with 2*n+10).  Return 0 safely. */
    free(q);
    return (seq_t)0;
}
